class Exchange {                                 // the seam: an interface
public:
    virtual ~Exchange() = default;
    virtual bool Send(const Order& o) = 0;
    virtual double LastPrice(std::string_view sym) const = 0;
};

class MockExchange : public Exchange {
public:
    MOCK_METHOD(bool, Send, (const Order& o), (override));
    MOCK_METHOD(double, LastPrice, (std::string_view sym), (const, override));
};

TEST(OrderServiceTest, BuysAtTheLastPrice) {
    MockExchange ex;
    EXPECT_CALL(ex, LastPrice("AAPL")).WillOnce(Return(190.0));
    EXPECT_CALL(ex, Send(Field(&Order::px, 190.0))).WillOnce(Return(true));
    OrderService svc(ex);                        // inject the mock
    EXPECT_TRUE(svc.BuyAtMarket("AAPL", 10));
}                                                // expectations verified here
